mapper.select:
select * from ( SELECT T1.ISSUE_AMT ISSUE_AMT,
,T2.TYPE_6
,T2.TYPE_9 ,T2.TYPE_10 ,T2.TYPE_11 ,T2.TYPE_12
,T6.CUSTOMER_NAME financierName ,T7.CUSTOMER_NAME sponsorName, T1.FINANCIER,T1.SPONSOR FROM FIN_PRODUCT T1 left join FIN_PRODUCT_TYPE T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T6 ON T6.CUSTOMER_ID = T1.FINANCIER LEFT JOIN MST_CUSTOMER_INFO T7 ON T7.CUSTOMER_ID = T1.SPONSOR )T
AND (T.FINPROD_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%') or T.FINPROD_NAME like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%'))
AND T.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T.CCY = #{ccy,jdbcType=VARCHAR}
AND T.TYPE_6 in
#{item}
AND T.TYPE_9 in
#{item}
AND T.TYPE_10 in
#{item}
AND T.TYPE_11 in
#{item}
AND T.TYPE_12 in
#{item}
AND T.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND T.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND T.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND T.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND T.FINANCIER = #{financier,jdbcType=VARCHAR}
AND T.SPONSOR = #{sponsor,jdbcType=VARCHAR}

SELECT T1.ISSUE_AMT ISSUE_AMT,
,T3.TYPE_6, T3.TYPE_7,
T3.TYPE_9, T3.TYPE_10, T3.TYPE_11, T3.TYPE_12,
T4.ASSET_SOURCE, T4.ASSET_PROVIDER, T4.ASSET_SOURCE_UNIT, T4.LOAD_BANK, T4.SETTLE_DAYS, t2.INVEST_NATURE, T4.PROJ_INVEST_INDUSTRY, T4.PROJ_INVEST_INDUSTRY2, T4.CASH_OUT_NO CASH_OUT_NO, T5.BUYOUT_RATE*100 BUYOUT_RATE, T.SEQNO pflsh, T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_FLAG creditFlag, T4.ACTUAL_CREDIT_PROVID actualCreditProvid, T1.FINANCIER financier, T1.SPONSOR sponsor, T6.REP_ASSET_TYPE, T4.TRIAL_NO, T1.CONTRACT_NO, T1.INVEST_ADVISER, T.SEQNO FROM FIN_PRODUCT T1 LEFT JOIN ( SELECT B.SEQNO , B.FINPROD_ID, A.CREDIT_FLAG, A.PFLSH, A.HAP_CREDIT_AMT , A.CUSTOMER_ID FROM (select t.CREDIT_FLAG,t.PFLSH,t.HAP_CREDIT_AMT, t.CUSTOMER_ID, ROW_NUMBER() over (partition by t.CUSTOMER_ID order by t.VDATE desc) RN from CREDIT_LINES t) A LEFT JOIN CREDIT_ASSETPOOL_DETAIL B ON B.SEQNO = A.CUSTOMER_ID where A.RN = 1 ) T ON (T.FINPROD_ID = T1.FINPROD_ID OR T.CUSTOMER_ID = T1.FINPROD_ID) LEFT JOIN FIN_PRODUCT_ADD T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T3 ON T3.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT_BUYOUT_RATE T5 ON T5.FINPROD_ID = T1.FINPROD_ID AND T5.EFF_DATE = T1.VDATE LEFT JOIN REP_ASSET_DEPT T6 on T1.FINPROD_ID = T6.REP_FINPROD_ID
T1.FINPROD_ID = #{finprodId}
T1.FINPROD_MARKET_ID = #{finprodMarketId}
